#include "main.h"
extern TIM_HandleTypeDef {{tim_handle}};

int main(void) {
  HAL_Init(); SystemClock_Config(); MX_GPIO_Init(); MX_TIM3_Init();
  HAL_TIM_PWM_Start(&{{tim_handle}}, {{channel}});
  uint32_t d = 0;
  while (1) {
    __HAL_TIM_SET_COMPARE(&{{tim_handle}}, {{channel}}, d);
    d = (d + 10) % 1000;
    HAL_Delay(20);
  }
}
